#include "common.h"
Passenger *load_passengers(void){FILE*f=fopen(PASS_FILE,"r");Passenger*h=NULL,**tail=&h,*n; if(!f)return NULL;while(1){n=calloc(1,sizeof*n);if(!n)break;int g;if(fscanf(f,"%d|%10[^|]|%d|%d|%63[^|]|%d|%47[^\n]\n",&n->train_number,n->date,&n->seat_number,&n->age,n->name,&g,n->username)!=7){free(n);break;}n->gender=(Gender)g;*tail=n;tail=&n->next;}fclose(f);return h;}
void save_passengers(Passenger*h){FILE*f=fopen(PASS_FILE,"w");if(!f){perror("Save passengers");return;}for(;h;h=h->next)fprintf(f,"%d|%s|%d|%d|%s|%d|%s\n",h->train_number,h->date,h->seat_number,h->age,h->name,(int)h->gender,h->username);fclose(f);}
void free_passengers(Passenger*h){while(h){Passenger*n=h->next;free(h);h=n;}}
static Train *find_train(Train*h,int no){for(;h;h=h->next)if(h->number==no)return h;return NULL;}
static int seat_taken(Passenger*h,int tr,const char*d,int seat){for(;h;h=h->next)if(h->train_number==tr&&!strcmp(h->date,d)&&h->seat_number==seat)return 1;return 0;}
static void book(const char*u,Train*t){int no=read_int("Train number: ",1,999999);Train*tr=find_train(t,no);if(!tr){puts("Train not found.");return;}char date[16];read_line("Journey date (YYYY-MM-DD, today to next 3 days): ",date,sizeof date);if(!valid_journey_date(date)){puts("Invalid date. Choose today through the next 3 days.");return;}int want=read_int("Number of passengers: ",1,100),got=0;Passenger*h=load_passengers(),*tail=h;while(tail&&tail->next)tail=tail->next;for(int i=0;i<want;i++){int seat;for(seat=1;seat<=tr->total_seats&&seat_taken(h,no,date,seat);seat++);if(seat>tr->total_seats){printf("No seats left. Booked %d of %d passengers; remaining passengers not booked.\n",got,want);break;}Passenger*n=calloc(1,sizeof*n);if(!n)break;n->train_number=no;n->seat_number=seat;strcpy(n->date,date);strcpy(n->username,u);read_line("Passenger name: ",n->name,sizeof n->name);if(!n->name[0]||strchr(n->name,'|')){puts("Invalid name; passenger skipped.");free(n);i--;continue;}n->age=read_int("Age: ",1,120);int g=read_int("Gender (1 Male, 2 Female, 3 Other): ",1,3);n->gender=(Gender)g;if(!h)h=n;else tail->next=n;tail=n;got++;printf("Seat %d confirmed for %s.\n",seat,n->name);}save_passengers(h);if(got==want)puts("Booking completed.");free_passengers(h);}
static void cancel(const char*u){int no=read_int("Train number: ",1,999999);char d[16];read_line("Journey date (YYYY-MM-DD): ",d,sizeof d);Passenger*h=load_passengers(),**pp=&h;int count=read_int("How many seat numbers to cancel? ",1,100),cancelled=0;for(int i=0;i<count;i++){int s=read_int("Seat number: ",1,10000);pp=&h;while(*pp&& !((*pp)->train_number==no&&!strcmp((*pp)->date,d)&&(*pp)->seat_number==s&&!strcmp((*pp)->username,u)))pp=&(*pp)->next;if(*pp){Passenger*x=*pp;*pp=x->next;printf("Cancelled seat %d (%s).\n",s,x->name);free(x);cancelled++;}else printf("Seat %d not found in your bookings.\n",s);}save_passengers(h);printf("Cancelled %d seat(s).\n",cancelled);free_passengers(h);}
static void details(const char*u){int no=read_int("Train number: ",1,999999);char d[16];read_line("Journey date (YYYY-MM-DD): ",d,sizeof d);int count=read_int("How many seat numbers to view? ",1,100);Passenger*h=load_passengers();for(int i=0;i<count;i++){int s=read_int("Seat number: ",1,10000),found=0;for(Passenger*p=h;p;p=p->next)if(p->train_number==no&&!strcmp(p->date,d)&&p->seat_number==s&&!strcmp(p->username,u)){printf("Train %d | %s | Seat %d | %s | Age %d | Gender %s | User %s\n",no,d,s,p->name,p->age,p->gender==MALE?"Male":p->gender==FEMALE?"Female":"Other",p->username);found=1;break;}if(!found)puts("No matching booking found.");}free_passengers(h);}
void booking_menu(const char*u,Train*trains){char c[16];for(;;){show_trains(trains);puts("\n-------------- MENU-2 --------------\nR/r: Reserve ticket\nC/c: Cancel ticket\nB/b: Booking details\nQ/q: Quit");read_line("Choose: ",c,sizeof c);if(c[0]=='R'||c[0]=='r')book(u,trains);else if(c[0]=='C'||c[0]=='c')cancel(u);else if(c[0]=='B'||c[0]=='b')details(u);else if(c[0]=='Q'||c[0]=='q')break;else puts("Invalid option.");}}
